begin;
create extension if not exists pgtap with schema extensions;
select plan(28);
insert into auth.users(id) values ('08000000-0000-4000-8000-000000000001'),('08000000-0000-4000-8000-000000000002'),('08000000-0000-4000-8000-000000000003'),('08000000-0000-4000-8000-000000000004');
insert into public.tenants(id,name,demo) values ('18000000-0000-4000-8000-000000000001','Public QR fictional',true);
insert into public.sites(id,tenant_id,name) values ('28000000-0000-4000-8000-000000000001','18000000-0000-4000-8000-000000000001','Public QR site');
insert into public.memberships(tenant_id,site_id,user_id,role,capabilities) values
 ('18000000-0000-4000-8000-000000000001','28000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000001','RESIDENT',array['visits.invite']),
 ('18000000-0000-4000-8000-000000000001','28000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000002','SITE_MANAGER',array['visits.forms.manage']),
 ('18000000-0000-4000-8000-000000000001','28000000-0000-4000-8000-000000000001','08000000-0000-4000-8000-000000000003','PLATFORM_OPERATOR',array['audit.read']);
update private.runtime_settings set environment='test',simulations_enabled=true;
create temp table public_ctx(name text primary key,data jsonb);
grant all on public_ctx to authenticated,anon;
create function pg_temp.start_checkin(r uuid default '38000000-0000-4000-8000-000000000001') returns jsonb language sql as $$select public.begin_site_checkin((select data->>'token' from public_ctx where name='qr'),r)$$;
create function pg_temp.create_tenant() returns uuid language sql as $$select public.create_platform_tenant('48000000-0000-4000-8000-000000000001','Fictional new township','Initial site','08000000-0000-4000-8000-000000000004')$$;
set local role anon;
select throws_ok($$select public.create_site_checkin_link('28000000-0000-4000-8000-000000000001')$$,'42501',null,'anonymous cannot issue site QR');
select throws_ok($$select public.get_platform_overview()$$,'42501',null,'anonymous cannot access platform');
set local role authenticated;
select set_config('request.jwt.claim.sub','08000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.create_site_checkin_link('28000000-0000-4000-8000-000000000001')$$,'42501','Forbidden','resident cannot issue public QR');
select throws_ok($$insert into public.platform_admins(user_id) values(auth.uid())$$,'42501',null,'resident cannot grant global authority');
select set_config('request.jwt.claim.sub','08000000-0000-4000-8000-000000000002',true);
insert into public_ctx values('qr',public.create_site_checkin_link('28000000-0000-4000-8000-000000000001'));
select ok((select data->>'token' from public_ctx where name='qr')~'^[a-f0-9]{64}$','public QR uses opaque token');
set local role anon;
select set_config('request.jwt.claim.sub','',true);
insert into public_ctx values('flow',pg_temp.start_checkin());
select is(pg_temp.start_checkin()->>'token',(select data->>'token' from public_ctx where name='flow'),'flow start retry returns same private token');
select ok((select data->>'token' from public_ctx where name='flow')<>(select data->>'token' from public_ctx where name='qr'),'public QR and private registration tokens differ');
select lives_ok($$select public.resolve_visitor_invitation((select data->>'token' from public_ctx where name='flow'))$$,'private flow resolves through normal registration contract');
select lives_ok($$select public.submit_visitor_registration((select data->>'token' from public_ctx where name='flow'),'Fictional walk-in',true,'{}')$$,'public QR visitor registers without account');
select throws_ok($$select pg_temp.start_checkin()$$,'P0001','Registration flow already used or expired','completed private flow cannot replay');
insert into public_ctx values('flow2',pg_temp.start_checkin('38000000-0000-4000-8000-000000000002'));
select ok((select data->>'token' from public_ctx where name='flow2')<>(select data->>'token' from public_ctx where name='flow'),'different visitor gets different private flow');
select throws_ok($$select * from private.site_checkin_flows$$,'42501',null,'anonymous cannot enumerate registration flows');
set local role authenticated;
select set_config('request.jwt.claim.sub','08000000-0000-4000-8000-000000000002',true);
select public.revoke_site_checkin_link('28000000-0000-4000-8000-000000000001',(select (data->>'id')::uuid from public_ctx where name='qr'));
set local role anon;
select throws_ok($$select pg_temp.start_checkin(gen_random_uuid())$$,'P0001','Site check-in unavailable','revoked site QR cannot start a new flow');
select lives_ok($$select public.resolve_visitor_invitation((select data->>'token' from public_ctx where name='flow2'))$$,'previous private flow keeps documented original expiry');
set local role authenticated;
select set_config('request.jwt.claim.sub','08000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.get_platform_overview()$$,'42501','Forbidden','site operator role alone is not global authorization');
select throws_ok($$select pg_temp.create_tenant()$$,'42501','Forbidden','unapproved operator cannot create tenant');
reset role;
insert into public.platform_admins(user_id) values('08000000-0000-4000-8000-000000000003');
update private.runtime_settings set environment='production',simulations_enabled=false;
set local role authenticated;
select throws_ok($$select pg_temp.create_tenant()$$,'42501','Multi-factor step-up required','global changes require MFA outside demo');
reset role;
update private.runtime_settings set environment='test',simulations_enabled=true;
set local role authenticated;
select lives_ok($$select public.get_platform_overview()$$,'explicit global metadata grant works');
select lives_ok($$select pg_temp.create_tenant()$$,'tenant and designated initial admin created atomically');
select lives_ok($$select pg_temp.create_tenant()$$,'tenant creation retry idempotent');
select is((select count(*)::int from public.visits),0,'global admin gains no implicit visitor PII');
select throws_ok($$select public.create_township_site('48000000-0000-4000-8000-000000000001',gen_random_uuid(),'Unauthorized site')$$,'42501','Forbidden','platform metadata grant is not township membership');
select set_config('request.jwt.claim.sub','08000000-0000-4000-8000-000000000004',true);
select lives_ok($$select public.create_township_site('48000000-0000-4000-8000-000000000001','58000000-0000-4000-8000-000000000001','Second site')$$,'assigned township admin creates site');
select lives_ok($$select public.create_township_site('48000000-0000-4000-8000-000000000001','58000000-0000-4000-8000-000000000001','Second site')$$,'site creation retry idempotent');
select throws_ok($$select public.create_township_site('18000000-0000-4000-8000-000000000001',gen_random_uuid(),'Foreign site')$$,'42501','Forbidden','township admin cannot create foreign tenant site');
select is((select count(*)::int from public.sites where tenant_id='48000000-0000-4000-8000-000000000001'),2,'new admin sees only explicitly granted sites');
select is((select count(*)::int from public.platform_admins),0,'township admin cannot enumerate global grants');
select ok(has_table_privilege('service_role','public.platform_admins','INSERT') and has_table_privilege('service_role','public.iot_devices','SELECT'),'trusted seed and bridge grants do not depend on hosted defaults');
select * from finish();
rollback;
